import React, { useState, useEffect } from 'react';
import DepartmentCard from './components/DepartmentCard';
import ScheduleCalendar from './components/ScheduleCalendar';
import ConflictTable from './components/ConflictTable';
import { 
  PlusCircle, LayoutDashboard, Database, 
  ShieldCheck, Printer, AlertTriangle, 
  Zap, Activity, Trash2 
} from 'lucide-react';

function App() {
  // 1. STATE INITIALIZATION (Ready for Supabase)
  const [departments, setDepartments] = useState([
    { 
      id: 1, 
      name: "College of Computer Studies", 
      code: "CCS",
      subjects: { 1: [], 2: [], 3: [], 4: [], 5: [] },
      proctors: [],
      rooms: []
    },
    { 
      id: 2, 
      name: "Business Administration", 
      code: "CBA",
      subjects: { 1: [], 2: [], 3: [], 4: [], 5: [] },
      proctors: [],
      rooms: []
    }
  ]);

  const [globalSchedule, setGlobalSchedule] = useState([]);
  const [allExamDates, setAllExamDates] = useState([]);

  // 2. CENTRAL DATA UPDATE HANDLER
  // This allows DeptCards to update the master list without owning the state
  const updateDeptData = (deptId, field, newData) => {
    setDepartments(prev => prev.map(d => 
      d.id === deptId ? { ...d, [field]: newData } : d
    ));
  };

  const addDepartment = () => {
    const name = prompt("Enter Department Name:");
    const code = prompt("Enter Department Code:");
    if (name && code) {
      setDepartments([...departments, { 
        id: Date.now(), 
        name, 
        code: code.toUpperCase(),
        subjects: { 1: [], 2: [], 3: [], 4: [], 5: [] },
        proctors: [],
        rooms: []
      }]);
    }
  };

  const handleScheduleGenerated = (newAssignments, newDates, deptCode) => {
    const processedNewData = newAssignments.map(session => ({
      ...session,
      id: `${deptCode}-${Date.now()}-${Math.random()}`,
      dept_code: deptCode,
    }));

    setGlobalSchedule(prev => {
      const otherDepts = prev.filter(item => item.dept_code !== deptCode);
      const combinedList = [...otherDepts, ...processedNewData];

      return combinedList.map(item => {
        const conflict = combinedList.find(target => 
          target.id !== item.id && 
          target.exam_date === item.exam_date &&
          (target.room === item.room || target.proctor === item.proctor) &&
          (item.start_time < target.end_time && item.end_time > target.start_time)
        );
        return { 
          ...item, 
          hasConflict: !!conflict, 
          conflictWith: conflict?.dept_code,
          conflictType: conflict ? (conflict.room === item.room ? 'ROOM' : 'PROCTOR') : null
        };
      });
    });

    if (newDates?.length > 0) {
      setAllExamDates(prev => {
        const combined = [...new Set([...prev, ...newDates])];
        return combined.filter(d => d).sort((a, b) => new Date(a) - new Date(b));
      });
    }
  };

  const conflictCount = globalSchedule.filter(s => s.hasConflict).length;

  return (
    <div className="min-h-screen bg-slate-50 pb-24 font-sans text-slate-900">
      <nav className="bg-slate-900 px-8 py-5 mb-10 flex justify-between items-center sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-3">
          <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-500/20">
            <LayoutDashboard size={24} className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-black text-white tracking-tighter uppercase">
              Exam_Flow <span className="text-blue-500 text-[10px] ml-1 tracking-widest">PRO v2.0</span>
            </h1>
          </div>
        </div>

        <div className="flex items-center gap-6">
            <div className={`flex items-center gap-3 px-5 py-2.5 rounded-2xl border transition-all ${conflictCount > 0 ? 'bg-rose-500/10 border-rose-500/50' : 'bg-emerald-500/10 border-emerald-500/50'}`}>
                <span className={`text-[10px] font-black uppercase tracking-widest ${conflictCount > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                  {conflictCount > 0 ? `${conflictCount} Overlaps` : 'Synchronized'}
                </span>
            </div>
            <button onClick={addDepartment} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-xs uppercase flex items-center gap-2">
              <PlusCircle size={18} /> New Dept
            </button>
        </div>
      </nav>

      <main className="container mx-auto px-6 max-w-7xl">
        <ConflictTable schedule={globalSchedule} />

        <div className="space-y-12">
          {departments.map((dept) => (
            <DepartmentCard 
              key={dept.id} 
              dept={dept}
              onUpdate={(field, data) => updateDeptData(dept.id, field, data)}
              globalSchedule={globalSchedule}
              onGenerate={(schedule, dates) => handleScheduleGenerated(schedule, dates, dept.code)}
            />
          ))}
        </div>

        <div className="mt-24 pt-24 border-t-2 border-slate-200/60">
            {globalSchedule.length > 0 ? (
                <ScheduleCalendar scheduleData={globalSchedule} examDates={allExamDates} />
            ) : (
                <div className="py-40 bg-white rounded-[4rem] border-4 border-dashed border-slate-200 text-center text-slate-300 font-black uppercase">
                    System Idle: Generate a schedule to begin
                </div>
            )}
        </div>
      </main>
    </div>
  );
}

export default App;
